ALTER TABLE applications ADD COLUMN registration_category TEXT;
ALTER TABLE applications ADD COLUMN guardian_name TEXT NOT NULL DEFAULT '';
ALTER TABLE applications ADD COLUMN guardian_email TEXT NOT NULL DEFAULT '';
ALTER TABLE applications ADD COLUMN guardian_phone TEXT NOT NULL DEFAULT '';
ALTER TABLE applications ADD COLUMN contact_recipient TEXT NOT NULL DEFAULT 'student';
ALTER TABLE applications ADD COLUMN enrollment_year INTEGER;
ALTER TABLE applications ADD COLUMN existing_student_id TEXT REFERENCES students(id);
ALTER TABLE intakes ADD COLUMN year INTEGER;
ALTER TABLE intakes ADD COLUMN month INTEGER;
UPDATE intakes SET year=CAST(substr(id,1,4) AS INTEGER),month=CAST(substr(id,6,2) AS INTEGER) WHERE id GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]' AND CAST(substr(id,6,2) AS INTEGER) BETWEEN 1 AND 12;
UPDATE applications SET registration_category=CASE category WHEN 'class-plus-visa' THEN 'visa' WHEN 'class-only' THEN 'general' ELSE category END;
ALTER TABLE students ADD COLUMN original_category TEXT;
ALTER TABLE students ADD COLUMN original_year INTEGER;
ALTER TABLE students ADD COLUMN original_intake_id TEXT REFERENCES intakes(id);
ALTER TABLE students ADD COLUMN number_scheme TEXT NOT NULL DEFAULT 'legacy';
ALTER TABLE students ADD COLUMN guardian_name TEXT NOT NULL DEFAULT '';
ALTER TABLE students ADD COLUMN guardian_email TEXT NOT NULL DEFAULT '';
ALTER TABLE students ADD COLUMN guardian_phone TEXT NOT NULL DEFAULT '';
ALTER TABLE students ADD COLUMN contact_recipient TEXT NOT NULL DEFAULT 'student';
CREATE TABLE student_number_registry(number TEXT PRIMARY KEY,student_id TEXT REFERENCES students(id),reserved_application_id TEXT REFERENCES applications(id),scheme TEXT NOT NULL,assigned_at TEXT NOT NULL);
INSERT OR IGNORE INTO student_number_registry SELECT student_number,id,NULL,'legacy',created_at FROM students;
INSERT OR IGNORE INTO student_number_registry SELECT reserved_student_number,student_id,id,'legacy',updated_at FROM applications WHERE reserved_student_number IS NOT NULL;
CREATE TABLE visa_number_sequences(year INTEGER NOT NULL,month INTEGER NOT NULL,next_sequence INTEGER NOT NULL CHECK(next_sequence BETWEEN 1 AND 1000),PRIMARY KEY(year,month));
CREATE TABLE enrollments(id TEXT PRIMARY KEY,student_id TEXT NOT NULL REFERENCES students(id),application_id TEXT NOT NULL UNIQUE REFERENCES applications(id),category TEXT NOT NULL CHECK(category IN ('visa','ol','al','general','kids')),course_id TEXT REFERENCES courses(id),intake_id TEXT REFERENCES intakes(id),enrollment_year INTEGER NOT NULL,status TEXT NOT NULL DEFAULT 'Enrolled',confirmed_by TEXT REFERENCES users(id),confirmed_at TEXT NOT NULL,updated_at TEXT NOT NULL,CHECK((category='visa' AND intake_id IS NOT NULL) OR (category<>'visa' AND intake_id IS NULL)));
CREATE TABLE enrollment_history(id TEXT PRIMARY KEY,enrollment_id TEXT NOT NULL REFERENCES enrollments(id),category TEXT NOT NULL,course_id TEXT,intake_id TEXT,enrollment_year INTEGER NOT NULL,status TEXT NOT NULL,actor_id TEXT REFERENCES users(id),created_at TEXT NOT NULL);
CREATE TABLE enrollment_notifications(application_id TEXT PRIMARY KEY REFERENCES applications(id),campaign_id TEXT REFERENCES campaigns(id),actor_id TEXT REFERENCES users(id),error TEXT,created_at TEXT NOT NULL);
CREATE TABLE student_number_review(id INTEGER PRIMARY KEY AUTOINCREMENT,student_id TEXT REFERENCES students(id),application_id TEXT REFERENCES applications(id),number TEXT NOT NULL,reason TEXT NOT NULL,created_at TEXT NOT NULL,resolved_at TEXT);
INSERT INTO student_number_review(student_id,number,reason,created_at) SELECT id,student_number,'Legacy student number does not contain exactly 7 numeric digits.',strftime('%Y-%m-%dT%H:%M:%fZ','now') FROM students WHERE length(student_number)<>7 OR student_number GLOB '*[^0-9]*';
INSERT INTO student_number_review(application_id,number,reason,created_at) SELECT id,reserved_student_number,'Previously assigned application number retained; review before confirming enrollment.',strftime('%Y-%m-%dT%H:%M:%fZ','now') FROM applications WHERE reserved_student_number IS NOT NULL AND student_id IS NULL;
INSERT INTO student_number_review(application_id,number,reason,created_at) SELECT id,reserved_student_number,'Number shared by multiple legacy application reservations; confirm whether these are the same student.',strftime('%Y-%m-%dT%H:%M:%fZ','now') FROM applications WHERE reserved_student_number IN (SELECT reserved_student_number FROM applications WHERE reserved_student_number IS NOT NULL GROUP BY reserved_student_number HAVING COUNT(*)>1);
INSERT INTO enrollments SELECT 'legacy-'||a.id,a.student_id,a.id,a.registration_category,a.course_id,CASE WHEN a.registration_category='visa' THEN a.intake_id ELSE NULL END,CAST(substr(a.updated_at,1,4) AS INTEGER),'Enrolled',NULL,a.updated_at,a.updated_at FROM applications a WHERE a.student_id IS NOT NULL AND a.status='Enrolled' AND (a.registration_category<>'visa' OR a.intake_id IS NOT NULL);
INSERT INTO enrollment_history SELECT 'legacy-'||id,id,category,course_id,intake_id,enrollment_year,status,NULL,confirmed_at FROM enrollments;
UPDATE applications SET enrollment_year=(SELECT enrollment_year FROM enrollments e WHERE e.application_id=applications.id) WHERE status='Enrolled';
CREATE INDEX enrollments_student ON enrollments(student_id,confirmed_at);
CREATE INDEX enrollments_filters ON enrollments(category,enrollment_year,intake_id,status);
CREATE INDEX application_categories ON applications(registration_category,enrollment_year);
CREATE TRIGGER new_student_number_valid BEFORE INSERT ON students WHEN NOT EXISTS(SELECT 1 FROM student_number_registry WHERE number=NEW.student_number AND scheme='legacy') AND (typeof(NEW.student_number)<>'text' OR length(NEW.student_number)<>7 OR NEW.student_number GLOB '*[^0-9]*') BEGIN SELECT RAISE(ABORT,'Student number must contain exactly 7 numeric digits'); END;
CREATE TRIGGER student_number_immutable BEFORE UPDATE OF student_number ON students WHEN NEW.student_number<>OLD.student_number BEGIN SELECT RAISE(ABORT,'Assigned student numbers are immutable'); END;
CREATE TRIGGER student_origin_immutable BEFORE UPDATE OF original_category,original_year,original_intake_id,number_scheme ON students WHEN OLD.number_scheme<>'legacy' AND (NEW.original_category IS NOT OLD.original_category OR NEW.original_year IS NOT OLD.original_year OR NEW.original_intake_id IS NOT OLD.original_intake_id OR NEW.number_scheme<>OLD.number_scheme) BEGIN SELECT RAISE(ABORT,'Original student number metadata is immutable'); END;
INSERT INTO audit_events(actor_name,action,record_type,details,created_at) VALUES('System migration','Added registration categories and preserved legacy number review','settings','{"migration":"004","legacyClassOnlyMappedTo":"general","originalCategoryRetained":true}',strftime('%Y-%m-%dT%H:%M:%fZ','now'));
